import {PaperDoll,SLOTS,DEFAULT_OUTFIT,ACTIONS,loadArt,progressForFrame,setArtSource,artSource} from './art-router.js';
try{await loadArt();document.getElementById('art-status').textContent='Blender · sprite แยกชั้นทุกเฟรม · โมเดลทดลองเทียบกับตัวเดิม';}
catch(error){document.getElementById('art-status').textContent=error.message+' · ลองรีโหลดหน้านี้';for(const button of document.querySelectorAll('button'))button.disabled=true;throw error;}
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d'),doll=new PaperDoll();
ctx.imageSmoothingEnabled=false;
const state={outfit:{...DEFAULT_OUTFIT},accessories:{ring:'none',necklace:'none'},mode:'idle',time:0,paused:false,scale:3,mirror:false,hit:false,hits:0,autoIndex:0};
let lastTime=0,autoWait=0,fx=[],numbers=[],shake=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const icons={};
const iconDoll=new PaperDoll();
// Assign short explicit control names after the rows are mounted.
queueMicrotask(()=>{for(const [key,spec] of Object.entries(SLOTS))$(`equip-${key}`).setAttribute('aria-label',spec.label);});
// No API calls, payments or saves. Native layer state is exposed for prototype QA.
window.wardrobePrototype={state,getLayers:()=>doll.layers,getPose:()=>doll.draw(state.outfit,state.mode,progress()).pose,play:action=>play(action)};
function choiceLabel(slot,value){return SLOTS[slot].choices.find(c=>c[0]===value)?.[1]||value;}
function updateEquipment(){for(const k of Object.keys(SLOTS)){const select=$(`equip-${k}`);select.value=state.outfit[k];$(`remove-${k}`).disabled=state.outfit[k]==='none';const c=icons[k].getContext('2d');c.clearRect(0,0,64,64);iconDoll.draw({...Object.fromEntries(Object.keys(SLOTS).map(s=>[s,'none'])),[k]:state.outfit[k]},'idle',0);c.imageSmoothingEnabled=false;c.drawImage(iconDoll.layers[k],0,0,64,64);if(state.outfit[k]==='none'){c.fillStyle='#667267';c.fillRect(24,31,16,2);}}
  const visual=Object.entries(state.outfit).filter(([,v])=>v!=='none').map(([k,v])=>choiceLabel(k,v));let text=visual.length?visual.join(' · '):'ถอดอุปกรณ์ทั้งหมด เหลือตัวฐานและชุดชั้นใน';const accessories=[state.accessories.ring,state.accessories.necklace].filter(v=>v!=='none');if(accessories.length)text+=` · เครื่องประดับ ${accessories.length} ชิ้น (ไม่แสดงภาพ)`;$('summary').textContent=text;
}
function buildEquipment(){ $('equipment').replaceChildren(); for(const [key,spec] of Object.entries(SLOTS)){const row=document.createElement('div');row.className='slot';const icon=document.createElement('canvas');icon.width=icon.height=64;icon.className='slot-icon';icon.setAttribute('aria-hidden','true');icons[key]=icon;const label=document.createElement('label');label.htmlFor=`equip-${key}`;const title=document.createElement('span');title.textContent=spec.label;const select=document.createElement('select');select.id=`equip-${key}`;select.setAttribute('aria-label',spec.label);for(const [value,name] of spec.choices){const o=document.createElement('option');o.value=value;o.textContent=name;select.append(o);}select.addEventListener('change',()=>{state.outfit[key]=select.value;updateEquipment();});label.append(title,select);const remove=document.createElement('button');remove.type='button';remove.id=`remove-${key}`;remove.setAttribute('aria-label',`ถอด${spec.label}`);remove.title=`ถอด${spec.label}`;remove.innerHTML='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15"/></svg>';remove.addEventListener('click',()=>{state.outfit[key]='none';updateEquipment();});row.append(icon,label,remove);$('equipment').append(row);}
}
buildEquipment();
$('unequip').addEventListener('click',()=>{for(const k of Object.keys(SLOTS))state.outfit[k]='none';updateEquipment();});
$('restore').addEventListener('click',()=>{state.outfit={...DEFAULT_OUTFIT};updateEquipment();});
$('alternate').addEventListener('click',()=>{state.outfit=artSource()==='3d'?{hat:'helm',shirt:'plate',pants:'leather',weapon:'sabre',wrist:'cuff',boots:'greaves'}:{...DEFAULT_OUTFIT,hat:'hood'};updateEquipment();});
for(const key of ['ring','necklace'])$(key).addEventListener('change',()=>{state.accessories[key]=$(key).value;updateEquipment();});
$('scale').addEventListener('change',()=>state.scale=Number($('scale').value));
$('mirror').addEventListener('change',()=>state.mirror=$('mirror').checked);
$('walk').addEventListener('change',()=>{if(!ACTIONS[state.mode].impact){state.mode=$('walk').checked?'walk':'idle';state.time=0;updatePoseLabel();}});
function progress(){return Math.min(1,state.time/ACTIONS[state.mode].duration);}
function updatePoseLabel(){$('pose-label').textContent=ACTIONS[state.mode].label;for(const b of document.querySelectorAll('[data-action]')){b.classList.toggle('active',b.dataset.action===state.mode);b.setAttribute('aria-pressed',String(b.dataset.action===state.mode));}$('scrub').max=ACTIONS[state.mode].frames-1;}
function pause(value){state.paused=value;$('pause').textContent=value?'เล่นต่อ':'หยุดภาพ';$('pause').setAttribute('aria-pressed',String(value));}
$('pause').addEventListener('click',()=>pause(!state.paused));
$('scrub').addEventListener('input',()=>{pause(true);state.time=progressForFrame(state.mode,Number($('scrub').value))*ACTIONS[state.mode].duration;});
let lastAction='attack';
function play(action){if(!['attack','slam','leap'].includes(action))return;state.mode=action;state.time=0;state.hit=false;fx=[];numbers=[];shake=0;pause(false);lastAction=action;autoWait=0;updatePoseLabel();$('action-note').textContent=state.outfit.weapon==='none'?'ไม่ได้ใส่อาวุธ · ใช้ท่าเดิมด้วยมือเปล่า':action==='leap'?'กระโดด → พุ่งกลางอากาศ → โจมตี → ลงพื้น':action==='slam'?'ยกอาวุธเหนือหัว → ฟาดลง → หยุดภาพสั้นตอนโดน':'ง้างสั้น → ฟันเร็ว → คืนท่า';}
for(const b of document.querySelectorAll('[data-action]'))b.addEventListener('click',()=>play(b.dataset.action));
$('replay').addEventListener('click',()=>play(lastAction));
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||e.target.closest('input,select,textarea,button,[contenteditable]'))return;const action={j:'attack',k:'slam',l:'leap'}[e.key.toLowerCase()];if(action){e.preventDefault();play(action);}});
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function scene(time){const w=640,h=340;rect(0,0,w,h,'#172822');rect(0,0,w,195,'#24382e');const drift=$('walk').checked?time*.013:0;for(let j=0;j<3;j++){const shade=['#2e4434','#344d37','#3d563b'][j];for(let i=-1;i<12;i++){const x=(i*79+j*28-drift*(j+1))%740;const tall=70+(i*13+j*17)%45;rect(x,274-tall,13,tall,shade);rect(x-14,267-tall,40,23,shade);rect(x-6,251-tall,25,17,shade);rect(x+4,272-tall,24,27,shade);}}rect(0,284,w,56,'#343c2a');rect(0,283,w,3,'#6a8050');for(let i=0;i<32;i++){const x=(i*25-drift*4)%670;rect(x,290+(i*11)%36,5+(i%4),2,'#535843');}rect(0,316,640,24,'#2c3227');}
function dummy(x,ground,hitAge){const shakeX=hitAge<100?Math.sin(hitAge*.15)*(100-hitAge)*.07:0;x+=shakeX;rect(x-3,ground-55,6,55,'#866045');rect(x-12,ground-47,24,19,'#634934');rect(x-11,ground-46,22,4,'#ad8854');rect(x-9,ground-35,18,2,'#ab8758');rect(x-20,ground-33,41,5,'#866045');rect(x-11,ground-57,22,14,'#6f6845');rect(x-9,ground-57,18,2,'#b7a073');rect(x-14,ground-1,28,3,'#634934');if(hitAge<100){rect(x-12,ground-47,24,2,'#ffe3a2');}}
let worldTime=0,hitTime=-9999,hold=0;
function onImpact(){state.hit=true;state.hits++;hitTime=worldTime;hold=reduced?0:state.mode==='slam'?70:state.mode==='attack'?38:55;shake=reduced?0:state.mode==='slam'?4:3;const direction=state.mirror?-1:1,target=320+direction*120;fx.push({x:target,y:269,age:0,type:state.mode});numbers.push({x:target,y:219,age:0,text:String(ACTIONS[state.mode].damage)});}
function effects(dt){for(const f of fx){f.age+=dt;const life=1-f.age/280;if(life<=0)continue;const direction=state.mirror?-1:1;ctx.strokeStyle='#f3de9b';ctx.lineWidth=3;ctx.beginPath();if(f.type==='slam'){ctx.lineWidth=7;ctx.moveTo(f.x-68*direction,f.y-120);ctx.quadraticCurveTo(f.x+35*direction,f.y-90,f.x+10*direction,f.y-5);}else if(f.type==='leap'){ctx.moveTo(f.x-48*direction,f.y-44);ctx.lineTo(f.x+12*direction,f.y-8);}else{ctx.arc(f.x-10*direction,f.y-30,24,-1.4,.7);}ctx.stroke();for(let i=0;i<8;i++){const a=i*Math.PI/4,d=(1-life)*35;rect(f.x+Math.cos(a)*d,f.y-12+Math.sin(a)*d,Math.max(1,3*life),Math.max(1,3*life),i%2?'#d7b474':'#f3de9b');}if(f.type!=='attack'){rect(f.x-33*(1-life),283,66*(1-life),3*life,'#d7b474');}}
  fx=fx.filter(f=>f.age<280);for(const n of numbers){n.age+=dt;ctx.fillStyle='#ffe3a2';ctx.font='bold 17px Tahoma';ctx.textAlign='center';ctx.fillText(n.text,n.x,n.y-n.age*.075);}numbers=numbers.filter(n=>n.age<600);
}
function render(dt){worldTime+=dt;scene(worldTime);const p=progress(),action=ACTIONS[state.mode],hero=doll.draw(state.outfit,state.mode,p),dir=state.mirror?-1:1,s=state.scale;let x=320+hero.pose.rootX*s*dir,y=284+hero.pose.rootY*s;const target=320+dir*120;dummy(target,284,worldTime-hitTime);rect(x-16*s,283,30*s,3,'#1b281e');ctx.save();if(shake>0){ctx.translate(Math.round(Math.sin(worldTime)*shake),Math.round(Math.cos(worldTime*.6)*shake));shake=Math.max(0,shake-dt*.025);}ctx.translate(Math.round(x),Math.round(y));ctx.scale(dir*s,s);ctx.rotate(hero.pose.bodyLean||0);ctx.drawImage(hero.image,-64,-94);if(hero.fx)ctx.drawImage(hero.fx,-64,-94);ctx.restore();effects(dt);const frame=hero.pose.frame;$('frame-label').textContent=`เฟรม ${frame+1} / ${action.frames}`;if(!state.paused)$('scrub').value=frame;}
function tick(timestamp){const dt=Math.max(0,lastTime?timestamp-lastTime:0);lastTime=timestamp;const elapsed=state.paused?0:dt;const a=ACTIONS[state.mode];if(!state.paused){if(hold>0)hold=Math.max(0,hold-dt);else state.time+=dt;if(a.impact&&!state.hit&&progress()>=a.impact)onImpact();if(state.time>=a.duration){if(a.impact){if($('auto').checked){autoWait+=dt;if(autoWait>450){const sequence=['attack','slam','leap'];play(sequence[state.autoIndex++%3]);}}else{state.mode=$('walk').checked?'walk':'idle';state.time=0;updatePoseLabel();}}else state.time%=a.duration;}if($('auto').checked&&!ACTIONS[state.mode].impact){autoWait+=dt;if(autoWait>650)play(['attack','slam','leap'][state.autoIndex++%3]);}}
  render(elapsed);requestAnimationFrame(tick);}
document.addEventListener('visibilitychange',()=>{lastTime=0;});
updateEquipment();updatePoseLabel();requestAnimationFrame(tick);

const savedOutfits={};
$('art-source').addEventListener('change',async()=>{const source=$('art-source').value;pause(true);savedOutfits[artSource()]={...state.outfit};$('art-source').disabled=true;$('art-status').textContent='กำลังเปลี่ยนภาพ…';try{await setArtSource(source);state.outfit=savedOutfits[source]||{...DEFAULT_OUTFIT};state.mode='idle';state.time=0;state.hit=false;hold=0;buildEquipment();updateEquipment();updatePoseLabel();$('art-status').textContent=source==='3d'?'หัวพิกเซลตัวเดิม · ร่างกายและอุปกรณ์จาก Blender 3D · แยกชั้นทุกเฟรม':'PixelLab เดิม · ภาพเสื้อผ้าแปะตามจุดยึด (เพื่อเทียบ)';pause(false);}catch(err){$('art-status').textContent=err.message;$('art-source').value=artSource();}finally{$('art-source').disabled=false;}});
